function template(s){
  const c=s.config;
  const steps=[['1','이미지 추가','최대 3장을 추가하고 크기를 확인합니다.'],['2','노출 묶음','새 묶음의 순서와 태그를 정합니다.'],['3','이미지 이벤트 설정','좌우·조건·전환 방식을 설정합니다.'],['4','콘텐츠 편집','문구·이모지·스티커를 배치합니다.'],['5','검토·게시','합성 결과를 확인하고 게시합니다.']];
  return `<div data-banner-event-workflow="${s.kind}">
    <nav class="admin-card bew-map" aria-label="${c.label} 게시 절차">${steps.map(item=>`<button class="bew-map-step is-incomplete" data-bew-scroll="${item[0]}" data-step-state="incomplete" type="button"><span class="bew-map-node">${item[0]}</span><span class="bew-map-copy"><h3>${item[1]}</h3><p>${item[2]}</p><small class="bew-map-state" data-bew-step-state>미완료</small></span></button>`).join('')}</nav>
    <div class="admin-statusline bew-shell-status" data-bew-status aria-live="polite"></div>
    <section class="bew-result-banner" data-bew-result-notice role="status" aria-live="polite" hidden><div><strong data-bew-result-title></strong><p data-bew-result-copy></p></div><button class="admin-btn" data-bew-go-events type="button">이벤트 관리에서 확인</button></section>
    <div class="bew-flow">
      <div class="bew-step" id="bew-${s.kind}-1"><div class="bew-rail"><span>1</span></div><section class="admin-card bew-step-card"><div class="bew-head"><div><h3>이미지 추가</h3><p>카드를 눌러 한 장씩 추가하세요. 각 이미지의 저장 제목을 확인한 뒤 공통 분류 해시태그를 지정할 수 있습니다.</p></div><span class="bew-count" data-bew-file-count>0 / ${LIMIT}</span></div><input class="bew-hidden-input" data-bew-file-input type="file" accept="image/jpeg,image/png,image/webp" multiple><div class="bew-upload-grid" data-bew-upload-cards></div><div class="bew-upload-meta"><div class="bew-field"><span>분류 해시태그 · 선택 이미지 공통 적용 <b data-bew-tag-count>0 / 5</b></span><div class="bew-tags bew-upload-tags" data-bew-tag-editor><div class="bew-tag-list" data-bew-tag-list></div><input class="bew-tag-input" data-bew-tag-input maxlength="120" placeholder="입력 후 Enter 또는 쉼표" aria-label="분류 해시태그 입력" aria-describedby="bew-${s.kind}-tag-help bew-${s.kind}-tag-error"></div><small class="bew-tag-help" id="bew-${s.kind}-tag-help">Enter·쉼표·붙여넣기로 최대 5개를 추가합니다. 2번 라이브러리 필터에서 사용됩니다.</small><small class="bew-tag-error" id="bew-${s.kind}-tag-error" data-bew-tag-error aria-live="polite"></small></div><button class="admin-btn primary bew-upload-button" data-bew-upload type="button" disabled>선택 이미지 업로드</button></div><p class="bew-upload-note">저장 제목은 카드마다 따로 지정하며 라이브러리 전체에서 중복될 수 없습니다. 원본은 크기와 비율 그대로 저장되고, 업로드만으로는 게시되지 않습니다.</p><div class="admin-statusline" data-bew-upload-status></div></section></div>
      <div class="bew-step" id="bew-${s.kind}-2"><div class="bew-rail"><span>2</span></div><section class="admin-card bew-step-card"><div class="bew-head"><div><h3>새 노출 묶음 구성</h3><p>기존 게시 이미지가 자동으로 섞이지 않습니다. 이번 이벤트에 사용할 이미지만 새로 골라 순서를 정하세요.</p></div><span class="bew-count" data-bew-selected-count>0 / ${LIMIT}</span></div><div class="bew-bundle-meta"><label class="bew-field"><span>이벤트 이름</span><input class="admin-input" data-bew-bundle-name maxlength="120" placeholder="예: 푸석사과 신규 이미지"></label><p class="bew-bundle-help">해시태그는 1번에서 이미지 분류용으로 한 번만 지정합니다. 아래 라이브러리에서 같은 해시태그끼리 바로 골라볼 수 있습니다.</p></div><div class="bew-bundle-grid"><section class="bew-panel"><div class="bew-panel-head"><div><h4>이미지 라이브러리</h4><p>기본값은 미선택입니다. 전체 또는 해시태그를 눌러 이미지를 불러오세요.</p></div><span class="bew-limit-note" data-bew-library-limit>0장 선택 · 최대 ${LIMIT}장</span></div><div class="bew-filters" data-bew-filters></div><div class="bew-library" data-bew-library></div></section><section class="bew-panel"><div class="bew-panel-head"><div><h4>이미지 순서</h4><p>카드를 끌어서 놓거나 화살표를 눌러 1 → 2 → 3 순서를 정합니다.</p></div><span class="bew-limit-note" data-bew-order-limit>0 / ${LIMIT}</span></div><div class="bew-order-list" data-bew-order-list></div></section></div></section></div>
      <div class="bew-step" id="bew-${s.kind}-3"><div class="bew-rail"><span>3</span></div><section class="admin-card bew-step-card"><div class="bew-head"><div><h3>이미지 이벤트 설정</h3><p>언제 보여줄지와 이미지가 바뀌는 방법을 정합니다. 사이드 배너는 좌우를 같이 또는 따로 설정할 수 있습니다.</p></div><span class="bew-count">설정 가능</span></div><div data-bew-settings></div></section></div>
       <div class="bew-step" id="bew-${s.kind}-4"><div class="bew-rail"><span>4</span></div><section class="admin-card bew-step-card"><div class="bew-head"><div><h3>이미지별 콘텐츠 편집</h3><p>문구는 최대 3개, 이모지·이모티콘·스티커·뱃지는 합계 최대 3개까지 배치합니다. 등록한 꾸미기 이미지는 다른 캐릭터 이미지에도 다시 쓸 수 있습니다.</p></div><span class="bew-count">문구 3 + 꾸미기 3</span></div><div data-bew-overlay-editor></div></section></div>
       <div class="bew-step" id="bew-${s.kind}-5"><div class="bew-rail"><span>5</span></div><section class="admin-card bew-step-card"><div class="bew-head"><div><h3>검토하고 게시하기</h3><p>좌우 배치, 이미지 순서와 콘텐츠 합성 상태를 실제 노출 흐름대로 확인합니다.</p></div><span class="bew-count" data-bew-review-state>검토 대기</span></div><div data-bew-review></div></section></div>
     </div>
     <div class="bew-action-dock" data-bew-action-dock><div class="admin-statusline" data-bew-action-status aria-live="polite"></div><button class="admin-btn bew-reset-button" data-bew-reset type="button" disabled>내용 초기화</button><button class="admin-btn" data-bew-save-draft type="button" disabled>진행 중인 초안 저장</button><button class="admin-btn primary" data-bew-publish type="button" disabled>전체 게시</button></div>
     <div class="bew-reset-modal" data-bew-reset-modal aria-hidden="true" hidden><section class="bew-reset-dialog" data-bew-reset-dialog role="dialog" aria-modal="true" aria-labelledby="bew-${s.kind}-reset-title" aria-describedby="bew-${s.kind}-reset-description" tabindex="-1"><h3 id="bew-${s.kind}-reset-title">작성 중인 내용을 초기화하시겠습니까?</h3><p id="bew-${s.kind}-reset-description">현재 폼과 이 화면의 작성 상태만 비웁니다. 업로드된 라이브러리 이미지, 게시된 이벤트와 서버 기록은 삭제하지 않습니다.</p><div class="bew-reset-actions"><button class="admin-btn bew-reset-confirm" data-bew-reset-confirm type="button">초기화</button><button class="admin-btn" data-bew-reset-back type="button">뒤로</button></div></section></div>
   </div>`;
}

function warning(s,width,height){
  const expected=s.config.width/s.config.height,actual=width/height,different=Math.abs(actual-expected)>.003,small=width<s.config.width||height<s.config.height;
  if(different)return{kind:'',text:`원본 ${width}×${height} · 배너 비율과 달라 표시할 때 가장자리가 잘릴 수 있습니다.`};
  if(small)return{kind:'',text:`원본 ${width}×${height} · 배너보다 작아 확대 시 선명도가 낮아질 수 있습니다.`};
  return{kind:'safe',text:`원본 ${width}×${height} · 배너 비율과 일치합니다.`};
}
function titleLocalIssue(s,item,index){
  const title=normalizeTitle(item?.title);if(!title)return '저장 이미지 제목을 입력하세요.';if(title.length>120)return '저장 이미지 제목은 120자 이하로 입력하세요.';const key=titleKey(title);
  if(s.files.some((other,otherIndex)=>otherIndex!==index&&!other.assetId&&titleKey(other.title)===key))return '이번에 추가한 다른 이미지와 제목이 같습니다.';
  if(s.assets.some(asset=>Number(asset.assetId)!==Number(item.assetId||0)&&titleKey(assetTitle(asset))===key))return '이미지 라이브러리에 이미 같은 제목이 있습니다.';
  return '';
}
function titlePresentation(s,item,index){
  const issue=titleLocalIssue(s,item,index);if(issue)return{kind:'error',text:issue};if(item.assetId)return{kind:'ok',text:'저장 완료'};if(item.titleCheck==='checking')return{kind:'checking',text:'라이브러리 중복 여부 확인 중…'};if(item.titleCheck==='ok')return{kind:'ok',text:'사용 가능한 제목입니다.'};if(item.titleCheck==='error')return{kind:'error',text:item.titleMessage||'제목을 확인하지 못했습니다.'};return{kind:'checking',text:'중복 여부를 확인합니다.'};
}
function pendingTitlesReady(s){const pending=s.files.map((item,index)=>({item,index})).filter(({item})=>!item.assetId);return pending.length>0&&pending.every(({item,index})=>!titleLocalIssue(s,item,index)&&item.titleCheck==='ok')}
function refreshFileValidation(s){
  s.files.forEach((item,index)=>{const view=titlePresentation(s,item,index),input=$(`[data-bew-file-title="${index}"]`,s.root),stateNode=$(`[data-bew-title-state="${index}"]`,s.root);if(input)input.setAttribute('aria-invalid',view.kind==='error'?'true':'false');if(stateNode){stateNode.textContent=view.text;stateNode.className=`bew-title-state ${view.kind}`}});
  const button=$('[data-bew-upload]',s.root);if(button)button.disabled=!pendingTitlesReady(s)||s.busy;
}
async function checkFileTitle(s,index,{force=false}={}){
  const item=s.files[index];if(!item||item.assetId)return true;const issue=titleLocalIssue(s,item,index);if(issue){item.titleCheck='error';item.titleMessage=issue;refreshFileValidation(s);return false}if(!force&&item.titleCheck==='ok')return true;
  const requested=normalizeTitle(item.title),nonce=(item.titleNonce||0)+1;item.titleNonce=nonce;item.titleCheck='checking';item.titleMessage='';refreshFileValidation(s);
  try{const result=await api(s,'asset-title-check',{title:requested});if(!s.files.includes(item)||item.titleNonce!==nonce||titleKey(item.title)!==titleKey(requested))return false;item.titleCheck=result.available===true?'ok':'error';item.titleMessage=result.available===true?'':'이미지 라이브러리에 이미 같은 제목이 있습니다.';refreshFileValidation(s);return result.available===true}catch(error){if(s.files.includes(item)&&item.titleNonce===nonce){item.titleCheck='error';item.titleMessage=error.message||'제목 중복 여부를 확인하지 못했습니다.';refreshFileValidation(s)}return false}
}
function scheduleFileTitleCheck(s,index){const item=s.files[index];if(!item||item.assetId)return;window.clearTimeout(item.titleTimer);item.titleCheck='idle';item.titleMessage='';refreshFileValidation(s);item.titleTimer=window.setTimeout(()=>checkFileTitle(s,index),320)}
function tagIssue(tag){if(!tag)return '빈 해시태그는 추가할 수 없습니다.';if(tag.length>20)return `#${tag.slice(0,12)}…: 20자 이하로 입력하세요.`;if(!/^[0-9A-Za-z가-힣_-]+(?: [0-9A-Za-z가-힣_-]+)*$/.test(tag))return `#${tag}: 문자·숫자·공백·밑줄·하이픈만 사용할 수 있습니다.`;return ''}
function splitTagInput(value){const text=String(value||'').trim();if(!text)return[];if(text.includes('#'))return Array.from(text.matchAll(/#([^#,\n\r]+)/g),match=>match[1].trim()).concat(text.replace(/#[^#,\n\r]+/g,'').split(/[,\n\r]+/).map(part=>part.trim()).filter(Boolean));return text.split(/[,\n\r]+/).map(part=>part.trim()).filter(Boolean)}
function renderTagEditor(s,{focus=false}={}){const list=$('[data-bew-tag-list]',s.root),count=$('[data-bew-tag-count]',s.root),error=$('[data-bew-tag-error]',s.root),editor=$('[data-bew-tag-editor]',s.root),input=$('[data-bew-tag-input]',s.root);if(list)list.innerHTML=s.uploadTags.map((tag,index)=>`<span class="bew-tag">#${esc(tag)}<button class="bew-tag-remove" data-bew-tag-remove="${index}" type="button" aria-label="#${esc(tag)} 제거">×</button></span>`).join('');if(count)count.textContent=`${s.uploadTags.length} / 5`;if(error)error.textContent=s.tagError||'';editor?.classList.toggle('invalid',Boolean(s.tagError));if(focus&&input)input.focus();renderActions(s)}
function commitTags(s,value){const parts=splitTagInput(value);if(!parts.length)return;const next=[...s.uploadTags],keys=new Set(next.map(tag=>tag.toLocaleLowerCase('ko-KR')));s.tagError='';for(const raw of parts){const tag=normalizeTag(raw),issue=tagIssue(tag);if(issue){s.tagError=issue;break}const key=tag.toLocaleLowerCase('ko-KR');if(keys.has(key))continue;if(next.length>=5){s.tagError='분류 해시태그는 최대 5개까지 추가할 수 있습니다.';break}keys.add(key);next.push(tag)}s.uploadTags=next;const input=$('[data-bew-tag-input]',s.root);if(input)input.value='';s.activeStep=1;renderTagEditor(s,{focus:true})}
function renderFiles(s){
  const root=$('[data-bew-upload-cards]',s.root),count=$('[data-bew-file-count]',s.root),button=$('[data-bew-upload]',s.root);if(!root)return;
  const cards=s.files.map((item,index)=>{const report=warning(s,item.width,item.height),titleView=titlePresentation(s,item,index);return `<article class="bew-file-card"><div class="bew-file-thumb"><img class="bew-hover-image" data-bew-image-preview src="${esc(item.url)}" alt="${esc(item.file.name)} 미리보기" tabindex="0"><span class="bew-file-order">${index+1}</span></div><div class="bew-file-copy"><b title="${esc(item.file.name)}">${esc(item.file.name)}</b><small>${bytes(item.file.size)} · ${esc(item.file.type.replace('image/','').toUpperCase())}</small><label class="bew-file-title"><span>저장 이미지 제목</span><input class="admin-input" data-bew-file-title="${index}" maxlength="120" value="${esc(item.title||'')}" aria-invalid="${titleView.kind==='error'?'true':'false'}" ${item.assetId?'disabled':''}></label><span class="bew-title-state ${titleView.kind}" data-bew-title-state="${index}" aria-live="polite">${esc(titleView.text)}</span><strong class="bew-warning ${report.kind}">${esc(report.text)}</strong><span class="bew-file-state ${esc(item.stateKind||'')}">${esc(item.stateText||'업로드 대기')}</span><div class="bew-file-actions"><button class="bew-mini" data-bew-replace="${index}" type="button">바꾸기</button><button class="bew-mini danger" data-bew-file-remove="${index}" type="button">제거</button></div></div></article>`}).join('');
  const add=s.files.length<LIMIT?`<button class="bew-add-card" data-bew-add-card type="button"><span><strong>＋</strong>이미지 추가<small>선택하면 다음 카드가 생깁니다.</small></span></button>`:'';
  root.innerHTML=cards+add;count.textContent=`${s.files.length} / ${LIMIT}`;button.disabled=!pendingTitlesReady(s)||s.busy;renderActions(s);
}
function renderFilters(s){const root=$('[data-bew-filters]',s.root),tags=[...new Set(usableAssets(s).flatMap(assetTags))].sort((a,b)=>a.localeCompare(b,'ko'));if(!root)return;if(!['NONE','ALL',...tags].includes(s.filter))s.filter='NONE';root.innerHTML=[`<button class="bew-filter${s.filter==='NONE'?' active':''}" data-bew-filter="NONE" type="button">미선택</button>`,`<button class="bew-filter${s.filter==='ALL'?' active':''}" data-bew-filter="ALL" type="button">전체 ${usableAssets(s).length}</button>`,...tags.map(tag=>`<button class="bew-filter${s.filter===tag?' active':''}" data-bew-filter="${esc(tag)}" type="button">#${esc(tag)}</button>`)].join('')}
function renderLibrary(s){
  const root=$('[data-bew-library]',s.root),limit=$('[data-bew-library-limit]',s.root);if(!root)return;const selected=new Set(s.selected),assets=s.filter==='NONE'?[]:usableAssets(s).filter(asset=>s.filter==='ALL'||assetTags(asset).includes(s.filter));if(limit)limit.textContent=`${s.selected.length}장 선택 · 최대 ${LIMIT}장`;
  root.innerHTML=s.filter==='NONE'?'<div class="bew-empty">아직 라이브러리를 펼치지 않았습니다.<br><strong>전체</strong> 또는 <strong>#해시태그</strong>를 눌러 필요한 이미지만 불러오세요.</div>':assets.length?assets.map(asset=>{const id=Number(asset.assetId),chosen=selected.has(id),url=assetUrl(s,asset),title=assetTitle(asset),full=s.selected.length>=LIMIT&&!chosen;return `<article class="bew-asset"><img class="bew-hover-image" data-bew-image-preview src="${esc(url)}" alt="${esc(title)} 미리보기" tabindex="0"><div class="bew-asset-copy"><b title="${esc(title)}">${esc(title)}</b><small>${Number(asset.width)||'-'}×${Number(asset.height)||'-'}</small><span class="bew-state">${chosen?'이번 묶음':'업로드만'}</span><br><button class="bew-mini" data-bew-asset-add="${id}" type="button" ${chosen||full?'disabled':''} ${full?'title="최대 3장까지 추가할 수 있습니다."':''}>${chosen?'추가됨':full?'3장 선택 완료':'묶음에 추가'}</button></div></article>`}).join(''):`<div class="bew-empty">${s.filter==='ALL'?'업로드된 이미지가 없습니다. 위에서 먼저 이미지를 추가하세요.':`#${esc(s.filter)} 이미지가 없습니다.`}</div>`;
}
function renderOrder(s){
  const root=$('[data-bew-order-list]',s.root),count=$('[data-bew-selected-count]',s.root),limit=$('[data-bew-order-limit]',s.root);if(!root)return;const map=new Map(usableAssets(s).map(asset=>[Number(asset.assetId),asset]));
  const items=s.selected.map((id,index)=>({asset:map.get(Number(id)),id:Number(id),index})).filter(item=>item.asset);s.selected=items.map(item=>item.id);count.textContent=`${items.length} / ${LIMIT}`;if(limit)limit.textContent=`${items.length} / ${LIMIT} · ${items.length>=LIMIT?'최대 선택 완료':'추가 가능'}`;
  root.innerHTML=items.length?items.map(({asset,id,index})=>{const title=assetTitle(asset);return `<article class="bew-order-item" draggable="true" data-bew-order-drag="${id}"><span class="bew-drag-handle" aria-hidden="true">⋮⋮</span><span class="bew-order-number">${index+1}</span><img class="bew-hover-image" data-bew-image-preview src="${esc(assetUrl(s,asset))}" alt="${esc(title)} 미리보기" tabindex="0"><div class="bew-order-copy"><b>${esc(title)}</b><small>${index+1}${index===0?'번째로 시작':'번째로 노출'} · 끌어서 순서 변경</small></div><div class="bew-order-actions"><button class="bew-mini" data-bew-move="${id}" data-bew-direction="up" type="button" aria-label="앞 순서로" ${index===0?'disabled':''}>↑</button><button class="bew-mini" data-bew-move="${id}" data-bew-direction="down" type="button" aria-label="뒤 순서로" ${index===items.length-1?'disabled':''}>↓</button><button class="bew-mini danger" data-bew-selected-remove="${id}" type="button" aria-label="묶음에서 제거">×</button></div></article>`}).join(''):'<div class="bew-empty">아직 선택한 이미지가 없습니다.<br>왼쪽 라이브러리에서 최대 3장을 추가하세요.</div>';
}
function selectAsset(s,id){
  id=Number(id);if(!id||s.selected.includes(id)||s.selected.length>=LIMIT)return false;s.selected.push(id);
  if(s.assignmentsInitialized){for(const role of ['left','right'])if(!s.assignments[role].includes(id))s.assignments[role].push(id)}
  return true;
}
function removeSelected(s,id){id=Number(id);s.selected=s.selected.filter(value=>value!==id);for(const role of ['left','right'])s.assignments[role]=s.assignments[role].filter(value=>value!==id)}
