function itemPayloads(s,ids){const map=new Map(usableAssets(s).map(asset=>[Number(asset.assetId),asset]));return ids.filter(id=>map.has(Number(id))).map((id,index)=>({assetId:Number(id),weight:100,enabled:true,alt:String(map.get(Number(id))?.defaultAlt||'').trim(),clickUrl:null,sortOrder:index,scheduleMode:'INHERIT',startsAtKst:null,endsAtKst:null,weekdays:[],specificDates:[],contentOverlays:(s.overlays[Number(id)]||[]).map(layer=>({...layer,widthMode:layer.type==='TEXT'?'FULL':undefined}))}))}
