  if(active){const title={TEXT:'문구',EMOJI:'이모지',EMOTICON:'이모티콘',STICKER:'스티커',BADGE:'뱃지'}[active.type]||'콘텐츠',specific=active.type==='TEXT'?`<label class="bew-field bew-overlay-text"><span>문구 내용</span><textarea class="admin-textarea" data-bew-overlay-field="text" maxlength="300" placeholder="이미지와 함께 보여줄 문구를 입력하세요.">${esc(active.text)}</textarea></label>`:active.type==='EMOJI'?`<label class="bew-field"><span>이모지 또는 짧은 이모티콘</span><input class="admin-input" data-bew-overlay-field="emoji" maxlength="12" value="${esc(active.emoji)}"></label>`:`<div class="bew-flatten-note">선택 항목 · <strong>${esc(overlayAssetById(s,active.overlayAssetId)?.displayName||'등록 항목 없음')}</strong></div>`;editor=`<div class="bew-overlay-form"><div class="bew-overlay-form-head"><div><strong>${esc(assetTitle(asset))} · ${title}</strong><p>게시하면 원본과 이 레이어를 합친 별도 배너 이미지가 만들어집니다.</p></div><button class="bew-mini danger" data-bew-overlay-remove="${s.overlayLayerIndex}" type="button">레이어 삭제</button></div><label class="bew-overlay-enabled"><input data-bew-overlay-field="enabled" type="checkbox" ${active.enabled!==false?'checked':''}>이 콘텐츠 노출</label>${specific}${commonLayerControls(active)}${genericRanges(active)}${active.type==='TEXT'?`<div class="bew-overlay-colors"><label><span>텍스트 색</span><input data-bew-overlay-field="textColor" type="color" value="${esc(active.textColor)}"><b>${esc(active.textColor)}</b></label><label><span>배경색</span><input data-bew-overlay-field="backgroundColor" type="color" value="${esc(active.backgroundColor)}"><b>${esc(active.backgroundColor)}</b></label></div>`:''}<button class="admin-btn" data-bew-overlay-apply type="button">현재 이미지의 콘텐츠 전체를 선택한 ${s.overlayApply.length}장에 적용</button></div>`}
  root.innerHTML=contentLibraryMarkup(s,decorCount)+`<div class="bew-overlay-assets">${assets}</div><div class="bew-overlay-workspace"><aside class="bew-layer-list"><div class="bew-layer-head"><strong>콘텐츠 레이어</strong><span>문구 ${textCount}/3 · 꾸미기 ${decorCount}/3</span></div>${layerTabs}<div class="bew-layer-buttons"><button class="bew-layer-add" data-bew-overlay-add type="button" ${textCount>=3?'disabled':''}>＋ 문구</button><button class="bew-layer-add" data-bew-emoji-toggle type="button" ${decorCount>=3?'disabled':''}>＋ 이모지</button><div class="bew-content-palette">${EMOJIS.map(value=>`<button class="bew-emoji-button" data-bew-emoji-add="${esc(value)}" type="button" ${decorCount>=3?'disabled':''}>${esc(value)}</button>`).join('')}</div></div></aside><section class="bew-overlay-editor">${editor}</section><section class="bew-overlay-preview" data-bew-overlay-preview>${overlayPreviewMarkup(s)}</section></div>`;
